import '../../../core/network/v2/api_v2_client.dart';
import '../../../core/network/v2/api_v2_constants.dart';
import '../../../core/network/v2/paginated.dart';
import '../../models/v2/listing_summary.dart';
import '../../models/v2/owner_listing.dart';

/// Owner feed and the draft lifecycle for houses, land, cars and jobs.
///
/// Write payloads stay as maps because the backend accepts partial drafts and
/// screens build only the fields the user has filled in. `submission_key` is
/// generated by the caller and makes create retries idempotent.
class OwnerListingService {
  final ApiV2Client _client;

  OwnerListingService({ApiV2Client? client})
      : _client = client ?? ApiV2Client();

  Future<Paginated<OwnerListing>> fetch({
    String? cursor,
    int limit = ApiV2Constants.defaultLimit,
    ListingKind? type,
    OwnerListingStatus? status,
  }) {
    return _client.getCollection(
      ApiV2Constants.meListings,
      parse: OwnerListing.fromJson,
      query: {
        if (type != null && type != ListingKind.unknown) 'type': type.name,
        if (status != null && status != OwnerListingStatus.unknown)
          'status': status.wireValue,
        if (cursor != null && cursor.isNotEmpty) 'cursor': cursor,
        'limit': _clampLimit(limit),
      },
    );
  }

  Future<OwnerListing> createProperty(Map<String, dynamic> payload) {
    return _sendOwner(ApiV2Constants.listings, 'POST', payload);
  }

  Future<OwnerListing> updateProperty(
    int id,
    Map<String, dynamic> payload,
  ) {
    return _sendOwner(ApiV2Constants.listing(id), 'PATCH', payload);
  }

  Future<OwnerListing> createCar(Map<String, dynamic> payload) {
    return _sendOwner(ApiV2Constants.cars, 'POST', payload);
  }

  Future<OwnerListing> updateCar(int id, Map<String, dynamic> payload) {
    return _sendOwner(ApiV2Constants.car(id), 'PATCH', payload);
  }

  Future<OwnerListing> createJob(Map<String, dynamic> payload) {
    return _sendOwner(ApiV2Constants.jobs, 'POST', payload);
  }

  Future<OwnerListing> updateJob(int id, Map<String, dynamic> payload) {
    return _sendOwner(ApiV2Constants.job(id), 'PATCH', payload);
  }

  /// Runs completeness, KYC and quota gates and moves the listing to
  /// `pending`. The generic route works for every listing type.
  Future<OwnerListing> submit(int id) {
    return _sendOwner(ApiV2Constants.listingSubmit(id), 'POST', null);
  }

  Future<void> delete(int id) async {
    await _client.send(ApiV2Constants.listing(id), method: 'DELETE');
  }

  Future<OwnerListing> _sendOwner(
    String path,
    String method,
    Map<String, dynamic>? payload,
  ) async {
    final data = await _client.sendItem(path, method: method, body: payload);
    return OwnerListing.fromJson(data);
  }

  static int _clampLimit(int limit) {
    if (limit <= 0) return ApiV2Constants.defaultLimit;
    return limit > ApiV2Constants.maxLimit ? ApiV2Constants.maxLimit : limit;
  }
}
